"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def MAX_IN_WINDOW(arr, window_size):
    result = []
    for i in range(0, ((len(arr) - window_size) + 1)):
        max_value = float('-inf')
        for j in range(i, i + window_size):
            if (arr[j] > max_value):
                max_value = arr[j]
        result.append(max_value)
    return result
print(MAX_IN_WINDOW([1, 7, 3, 4, 5], 2))